import * as T from './vendor/three.module.js';
const signedPower=(v,e)=>Math.sign(v)*Math.pow(Math.abs(v),e);
export function sculptHead(detail='low'){const n=detail==='verylow'?12:detail==='high'?32:detail==='smooth'?28:20;const geometry=new T.SphereGeometry(1,n,detail==='verylow'?8:detail==='low'?12:20);const pos=geometry.attributes.position;for(let i=0;i<pos.count;i++){const y=T.MathUtils.clamp(pos.getY(i),-1,1),elevation=Math.asin(y),azimuth=Math.atan2(pos.getZ(i),pos.getX(i)),r=Math.pow(Math.max(0,Math.cos(elevation)),.52),height=.66*signedPower(Math.sin(elevation),.52),taper=1+height*.038;pos.setXYZ(i,.89*r*signedPower(Math.cos(azimuth),.52)*taper,height,.56*r*signedPower(Math.sin(azimuth),.52));}pos.needsUpdate=true;geometry.computeVertexNormals();return geometry;}
export function sculptFace(){const geometry=new T.PlaneGeometry(1.60,1.10,24,16),pos=geometry.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),y=pos.getY(i)-.04,taper=1+y*.038;const cross=Math.pow(Math.max(0,1-Math.pow(Math.abs(y/.66),2/.52)),1)-Math.pow(Math.abs(x/(.89*taper)),2/.52);const z=.56*Math.pow(Math.max(0,cross),.52/2);pos.setZ(i,z+.009);}geometry.computeVertexNormals();return geometry;}
export function bindSoftLimb(mesh,root,bones,upper,lower){root.updateMatrixWorld(true);const geometry=mesh.geometry.clone();const source=geometry.attributes.position;const localY=[];for(let i=0;i<source.count;i++)localY.push(source.getY(i)*mesh.scale.y+mesh.position.y);geometry.applyMatrix4(mesh.matrixWorld);const indices=[],weights=[];for(const y of localY){const blend=T.MathUtils.smoothstep(-y,.09,.26);indices.push(upper,lower,0,0);weights.push(1-blend,blend,0,0);}geometry.setAttribute('skinIndex',new T.Uint16BufferAttribute(indices,4));geometry.setAttribute('skinWeight',new T.Float32BufferAttribute(weights,4));const skin=new T.SkinnedMesh(geometry,mesh.material);skin.castShadow=true;skin.receiveShadow=true;root.add(skin);skin.bind(new T.Skeleton(bones));mesh.removeFromParent();mesh.geometry.dispose();return skin;}
